25 | 
26 |   async execute(args: { filePath: string; startLine?: number; endLine?: number; }): Promise<string> {
27 |     const { filePath, startLine, endLine } = args;
28 |     const fullPath = path.resolve(process.cwd(), filePath);
29 |     if (!fs.existsSync(fullPath)) return "Error: File not found.";
