4 |  * 用于通过通配符模式查找文件，替代 bash find/dir 命令
5 |  */
6 | import { z } from 'zod';
7 | import fg from 'fast-glob';
8 | import { resolve } from 'path';
9 | import { BaseTool } from './base';
10 | 
11 | const schema = z.object({
12 |     pattern: z.string().describe('Glob pattern like **/*.ts or src/**/*.test.ts'),
13 |     path: z.string().optional().describe('Base directory (default: current working directory)'),
14 |     limit: z.number().optional().describe('Maximum results to return (default: 100)')
15 | });
16 | 
17 | export default class GlobTool extends BaseTool<typeof schema> {
18 |     name = 'glob';
19 | 
20 |     description = `Fast file pattern matching tool.
21 | 
22 | BEST PRACTICES:
23 | - Use for finding files by extension or naming pattern
24 | - Prefer over bash find/dir commands for speed
25 | - Supports patterns: *.ts, **/*.test.ts, src/**/*.tsx
26 | - Automatically excludes node_modules, dist, .git, coverage
27 | - Returns files sorted by path
28 | 
29 | WHEN TO USE:
30 | - Finding all TypeScript files: *.ts
31 | - Finding test files: **/*.test.ts
32 | - Finding files in specific directory: src/**/*.ts
33 | - Avoid excessive wildcards: **/*.* is too broad
34 | 
35 | Returns array of relative file paths.`;
36 | 
37 |     schema = schema;
38 | 
39 |     async execute({ pattern, path = '.', limit = 100 }: z.infer<typeof schema>): Promise<string> {
40 |         try {
41 |             // 解析为绝对路径
42 |             const searchPath = resolve(process.cwd(), path);
43 | 
44 |             const files = await fg(pattern, {
45 |                 cwd: searchPath,
46 |                 absolute: false,
47 |                 ignore: [
48 |                     '**/node_modules/**',
49 |                     '**/dist/**',
50 |                     '**/.git/**',
51 |                     '**/coverage/**',
52 |                     '**/.next/**',
53 |                     '**/.nuxt/**',
54 |                     '**/build/**',
55 |                     '**/*.min.js',
56 |                     '**/*.min.css'
57 |                 ]
58 |             });
59 | 
60 |             // 手动限制结果数量
61 |             const limitedFiles = files.slice(0, limit);
62 | 
63 |             if (limitedFiles.length === 0) {
64 |                 return `No files found matching pattern: ${pattern} in ${path}`;
65 |             }
66 | 
67 |             const result = limitedFiles.join('\n');
68 | 
69 |             // 如果有更多结果被截断，添加提示
70 |             if (files.length > limit) {
71 |                 return `${result}\n... (${files.length - limit} more files, showing first ${limit})`;
72 |             }
73 | 
74 |             return result;
75 |         } catch (_error) {
76 |             const errorMsg = _error instanceof Error ? _error.message : String(_error);
77 |             return `Error: ${errorMsg}`;
78 |         }
79 |     }
80 | }
