40 |       '**/dist/**',
41 |       '**/.git/**',
42 |       '**/*.min.js',
43 |       '**/*.min.css',
44 |       '**/coverage/**',
45 |       '**/.next/**',
46 |       '**/.nuxt/**',
47 |       '**/build/**',
48 |     ];
49 | 
50 |     // 构建搜索选项
51 |     const options = {
52 |       caseSensitive: false,  // 智能大小写匹配
53 |       ignorePatterns,
54 |       // 如果指定了文件模式，添加 glob 过滤
55 |       // 注意：ripgrep-napi 没有直接的 glob 支持，需要通过 ignorePatterns 实现
56 |     };
