7 | 
8 | /**
9 |  * BatchReplaceTool - 批量替换工具
10 |  *
11 |  * 允许在单个调用中替换同一文件的多个位置，提高效率
12 |  */
13 | export class BatchReplaceTool extends BaseTool<any> {
14 | 
15 |   name = "batch_replace";
16 | 
17 |   description = "Replace multiple text segments in a file in a single call. Use for batch modifications like translating multiple comments or updating related JSDoc.";
18 | 
19 |   schema = z.object({
20 |     filePath: z.string().describe("Path to the file to modify"),
21 |     replacements: z.array(z.object({
22 |       line: z.number().describe("Line number (1-based)"),
23 |       oldText: z.string().describe("The exact text segment to replace"),
24 |       newText: z.string().describe("The new text")
25 |     })).describe("Array of replacements to apply in order")
26 |   });
27 | 
28 |   async execute({ filePath, replacements }: z.infer<typeof this.schema>): Promise<string> {
29 | 
30 |     const fullPath = path.resolve(process.cwd(), filePath);
31 | 
32 |     if (!fs.existsSync(fullPath)) {
33 |       return `Error: File not found: ${filePath}`;
34 |     }
35 | 
36 |     // 在修改前备份文件
37 |     const backupManager = getBackupManager();
38 |     await backupManager.initialize();
39 |     const backupId = await backupManager.backup(fullPath);
40 | 
41 |     const content = fs.readFileSync(fullPath, 'utf-8');
42 |     const lines = content.split('\n');
43 | 
44 |     const results: string[] = [];
45 |     let modifiedCount = 0;
46 | 
47 |     // Sort replacements by line number (descending) to avoid line number shifting issues
48 |     // Actually, for line-based replacement without shifting, we can process in any order
49 |     // since we're replacing text within lines, not adding/removing lines
50 | 
51 |     for (const repl of replacements) {
52 |       const { line, oldText, newText } = repl;
53 | 
54 |       if (line < 1 || line > lines.length) {
55 |         results.push(`❌ Line ${line}: out of range (file has ${lines.length} lines)`);
56 |         continue;
57 |       }
58 | 
59 |       const targetLineIdx = line - 1;
60 |       const originalLine = lines[targetLineIdx];
61 | 
62 |       if (!originalLine.includes(oldText)) {
63 |         results.push(`❌ Line ${line}: "${oldText}" not found. Content: "${originalLine.trim()}"`);
64 |         continue;
65 |       }
66 | 
67 |       const newLine = originalLine.replace(oldText, newText);
68 |       lines[targetLineIdx] = newLine;
69 |       modifiedCount++;
70 | 
71 |       console.log(chalk.yellow(`[Batch Edit] ${filePath}:${line}`));
72 |       console.log(chalk.red(`- ${originalLine.trim()}`));
73 |       console.log(chalk.green(`+ ${newLine.trim()}`));
74 |     }
