1 | /**
2 |  * ============================================================================
3 |  * File Backup Manager
4 |  * ============================================================================
5 |  *
6 |  * 自动备份和回滚机制，用于文件编辑操作的安全保护
7 |  */
8 | 
9 | import * as fs from 'fs/promises';
10 | import * as path from 'path';
11 | import * as crypto from 'crypto';
12 | import { ScopedLogger } from './log';
13 | 
14 | /**
15 |  * 备份信息
16 |  */
17 | export interface BackupInfo {
18 |     /** 备份 ID (唯一标识) */
19 |     id: string;
20 |     /** 原始文件路径 */
21 |     originalPath: string;
22 |     /** 备份文件路径 */
23 |     backupPath: string;
24 |     /** 创建时间戳 */
25 |     createdAt: number;
26 |     /** 文件大小 (bytes) */
27 |     size: number;
28 | }
29 | 
30 | /**
31 |  * 备份管理器配置
32 |  */
33 | export interface BackupManagerConfig {
34 |     /** 备份目录路径 */
35 |     backupDir?: string;
36 |     /** 每个文件最大备份数量 */
37 |     maxBackups?: number;
38 |     /** 是否启用备份 */
39 |     enabled?: boolean;
40 | }
41 | 
42 | /**
43 |  * 备份管理器
44 |  *
45 |  * 提供自动文件备份和回滚功能
46 |  */
47 | export class BackupManager {
48 |     private backupDir: string;
49 |     private maxBackups: number;
50 |     private enabled: boolean;
51 |     private logger: ScopedLogger;
52 |     private backupIndex: Map<string, BackupInfo[]> = new Map();
53 | 
54 |     constructor(config: BackupManagerConfig = {}) {
55 |         this.backupDir = config.backupDir || path.join(process.cwd(), '.claude', 'backups');
56 |         this.maxBackups = config.maxBackups ?? 5;
57 |         this.enabled = config.enabled ?? true;
58 |         this.logger = new ScopedLogger('BackupManager');
59 |     }
60 | 
61 |     /**
62 |      * 初始化备份管理器（创建备份目录）
63 |      */
64 |     async initialize(): Promise<void> {
65 |         if (!this.enabled) {
66 |             this.logger.debug('Backup manager is disabled');
67 |             return;
68 |         }
69 | 
70 |         try {
71 |             await fs.mkdir(this.backupDir, { recursive: true });
72 |             this.logger.debug(`Backup directory ready: ${this.backupDir}`);
73 |         } catch (error) {
74 |             this.logger.error(`Failed to create backup directory: ${error}`);
75 |             throw error;
76 |         }
77 |     }
78 | 
79 |     /**
80 |      * 备份文件
81 |      *
82 |      * @param filePath 要备份的文件路径
83 |      * @returns 备份 ID，如果备份失败返回 null
84 |      */
85 |     async backup(filePath: string): Promise<string | null> {
86 |         if (!this.enabled) {
87 |             return null;
88 |         }
89 | 
90 |         try {
91 |             // 检查文件是否存在
92 |             const stats = await fs.stat(filePath).catch(() => null);
93 |             if (!stats || !stats.isFile()) {
94 |                 this.logger.debug(`File not found, skipping backup: ${filePath}`);
95 |                 return null;
96 |             }
97 | 
98 |             // 读取文件内容
99 |             const content = await fs.readFile(filePath, 'utf-8');
100 | 
101 |             // 生成唯一备份 ID
102 |             const backupId = this.generateBackupId(filePath);
103 |             const backupPath = path.join(this.backupDir, `${backupId}.backup`);
104 | 
105 |             // 写入备份文件
106 |             await fs.writeFile(backupPath, content, 'utf-8');
107 | 
108 |             // 创建备份信息
109 |             const backupInfo: BackupInfo = {
110 |                 id: backupId,
111 |                 originalPath: filePath,
112 |                 backupPath,
113 |                 createdAt: Date.now(),
114 |                 size: stats.size,
115 |             };
116 | 
117 |             // 添加到索引
118 |             this.addToIndex(filePath, backupInfo);
119 | 
120 |             // 清理旧备份
121 |             await this.cleanOldBackups(filePath);
122 | 
123 |             this.logger.debug(`Backed up: ${filePath} -> ${backupId}`);
124 |             return backupId;
125 | 
126 |         } catch (error) {
127 |             this.logger.error(`Backup failed for ${filePath}: ${error}`);
128 |             return null;
129 |         }
130 |     }
131 | 
132 |     /**
133 |      * 恢复文件到指定备份
134 |      *
135 |      * @param filePath 原始文件路径
136 |      * @param backupId 备份 ID
137 |      * @returns 是否成功恢复
138 |      */
139 |     async restore(filePath: string, backupId: string): Promise<boolean> {
140 |         if (!this.enabled) {
141 |             this.logger.warn('Backup manager is disabled, cannot restore');
142 |             return false;
143 |         }
144 | 
145 |         try {
146 |             // 查找备份信息
147 |             const backups = this.backupIndex.get(filePath);
148 |             if (!backups) {
149 |                 this.logger.error(`No backups found for: ${filePath}`);
150 |                 return false;
151 |             }
152 | 
153 |             const backupInfo = backups.find(b => b.id === backupId);
154 |             if (!backupInfo) {
155 |                 this.logger.error(`Backup not found: ${backupId}`);
156 |                 return false;
157 |             }
158 | 
159 |             // 读取备份内容
160 |             const content = await fs.readFile(backupInfo.backupPath, 'utf-8');
161 | 
162 |             // 写入原始文件
163 |             await fs.writeFile(filePath, content, 'utf-8');
164 | 
165 |             this.logger.info(`Restored: ${filePath} from backup ${backupId}`);
166 |             return true;
167 | 
168 |         } catch (error) {
169 |             this.logger.error(`Restore failed for ${filePath}: ${error}`);
170 |             return false;
171 |         }
172 |     }
173 | 
174 |     /**
175 |      * 获取文件的所有备份
176 |      *
177 |      * @param filePath 文件路径
178 |      * @returns 备份信息列表（按创建时间降序）
179 |      */
180 |     getBackups(filePath: string): BackupInfo[] {
181 |         const backups = this.backupIndex.get(filePath);
182 |         return backups
183 |             ? [...backups].sort((a, b) => b.createdAt - a.createdAt)
184 |             : [];
185 |     }
186 | 
187 |     /**
188 |      * 删除指定备份
189 |      *
190 |      * @param filePath 文件路径
191 |      * @param backupId 备份 ID
192 |      */
193 |     async deleteBackup(filePath: string, backupId: string): Promise<void> {
194 |         const backups = this.backupIndex.get(filePath);
195 |         if (!backups) return;
196 | 
197 |         const backupInfo = backups.find(b => b.id === backupId);
198 |         if (backupInfo) {
199 |             await fs.unlink(backupInfo.backupPath).catch(() => {});
200 |             this.removeFromIndex(filePath, backupId);
201 |             this.logger.debug(`Deleted backup: ${backupId}`);
202 |         }
203 |     }
204 | 
205 |     /**
206 |      * 清理文件的所有旧备份
207 |      */
208 |     async clean(filePath: string): Promise<void> {
209 |         const backups = this.backupIndex.get(filePath);
210 |         if (!backups) return;
211 | 
212 |         for (const backup of backups) {
213 |             await fs.unlink(backup.backupPath).catch(() => {});
214 |         }
215 | 
216 |         this.backupIndex.delete(filePath);
217 |         this.logger.debug(`Cleared all backups for: ${filePath}`);
218 |     }
219 | 
220 |     /**
221 |      * 清理旧备份（保留最新的 maxBackups 个）
222 |      */
223 |     private async cleanOldBackups(filePath: string): Promise<void> {
224 |         const backups = this.backupIndex.get(filePath);
225 |         if (!backups || backups.length <= this.maxBackups) {
226 |             return;
227 |         }
228 | 
229 |         // 按创建时间排序，删除最旧的
230 |         const sortedBackups = [...backups].sort((a, b) => a.createdAt - b.createdAt);
231 |         const toDelete = sortedBackups.slice(0, sortedBackups.length - this.maxBackups);
232 | 
233 |         for (const backup of toDelete) {
234 |             await fs.unlink(backup.backupPath).catch(() => {});
235 |             this.removeFromIndex(filePath, backup.id);
236 |         }
237 |     }
238 | 
239 |     /**
240 |      * 生成备份 ID
241 |      */
242 |     private generateBackupId(filePath: string): string {
243 |         const hash = crypto
244 |             .createHash('md5')
245 |             .update(filePath + Date.now() + Math.random())
246 |             .digest('hex')
247 |             .substring(0, 12);
248 |         return `${path.basename(filePath)}_${hash}_${Date.now()}`;
249 |     }
250 | 
251 |     /**
252 |      * 添加到索引
253 |      */
254 |     private addToIndex(filePath: string, backupInfo: BackupInfo): void {
255 |         let backups = this.backupIndex.get(filePath);
256 |         if (!backups) {
257 |             backups = [];
258 |             this.backupIndex.set(filePath, backups);
259 |         }
260 |         backups.push(backupInfo);
261 |     }
262 | 
263 |     /**
264 |      * 从索引中删除
265 |      */
266 |     private removeFromIndex(filePath: string, backupId: string): void {
267 |         const backups = this.backupIndex.get(filePath);
268 |         if (!backups) return;
269 | 
270 |         const index = backups.findIndex(b => b.id === backupId);
271 |         if (index !== -1) {
272 |             backups.splice(index, 1);
273 |         }
274 | 
275 |         if (backups.length === 0) {
276 |             this.backupIndex.delete(filePath);
277 |         }
278 |     }
279 | }
280 | 
281 | // 单例实例
282 | let backupManagerInstance: BackupManager | null = null;
283 | 
284 | /**
285 |  * 获取全局备份管理器实例
286 |  */
287 | export function getBackupManager(config?: BackupManagerConfig): BackupManager {
288 |     if (!backupManagerInstance) {
289 |         backupManagerInstance = new BackupManager(config);
290 |     }
291 |     return backupManagerInstance;
292 | }
